contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // _from and _caddress are arbitrary, _tos is non-empty to avoid immediate require revert, v is arbitrary
    function run(address _from, address _caddress, address[] memory _tos, uint v) public payable {
        require(_tos.length > 0);
        // record balance of c before
        uint balBefore = address(c).balance;
        bool reverted;
        bool ret;
        // try calling transfer; capture revert status and return value if any
        try c.transfer(_from, _caddress, _tos, v) returns (bool r) {
            reverted = false;
            ret = r;
        } catch {
            reverted = true;
            ret = false;
        }
        // If the external call did not revert then it must have returned true, and c's balance must be unchanged
        assert(reverted || (ret == true && address(c).balance == balBefore));
    }
    receive() external payable { }
}

